'use strict';

// In-memory job queue behind the delivery worker. A job is any plain value.
// The queue hands one job out at a time and the worker reports back whether it
// went through; nothing here talks to the network.

const DEFAULT_MAX_ATTEMPTS = 3;

class JobQueue {
  constructor(options) {
    const opts = options || {};
    this.maxAttempts =
      typeof opts.maxAttempts === 'number' ? opts.maxAttempts : DEFAULT_MAX_ATTEMPTS;
    this.waiting = [];
    this.leased = new Map();
    this.nextId = 1;
  }

  // Adds a job and hands back the id the worker will report against.
  enqueue(job) {
    const id = 'j' + this.nextId;
    this.nextId += 1;
    this.waiting.push({ id: id, job: job, attempts: 0 });
    return id;
  }

  // How many jobs are still waiting to go out.
  size() {
    return this.waiting.length;
  }

  // Takes one job off the queue and records that it is out with a worker.
  dequeue() {
    const entry = this.waiting.pop();
    if (!entry) return null;
    entry.attempts += 1;
    this.leased.set(entry.id, entry);
    return { id: entry.id, job: entry.job, attempts: entry.attempts };
  }

  // The worker got it through.
  succeed(id) {
    this.leased.delete(id);
  }

  // The worker did not get it through, so it goes back on the queue.
  fail(id) {
    const entry = this.leased.get(id);
    if (!entry) return;
    this.leased.delete(id);
    this.waiting.push(entry);
  }
}

module.exports = { JobQueue };

