'use strict';

// The worker loop's only door into the queue. Nothing else in the service
// calls the queue directly, so whatever policy we want lives in here.
async function runOne(queue, handler) {
  const entry = queue.dequeue();
  if (!entry) return { ran: false };
  const value = await handler(entry.job, entry);
  queue.succeed(entry.id);
  return { ran: true, id: entry.id, value: value };
}

module.exports = { runOne };

