'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { JobQueue, fromSnapshot } = require('./src/queue.js');
const { runOne, drain } = require('./src/dispatcher.js');

// Empties a queue and reports the payloads in the order they came out.
function orderOut(queue, now) {
  const seen = [];
  for (let guard = 0; guard < 100; guard += 1) {
    const entry = queue.dequeue(now);
    if (!entry) return seen;
    seen.push(entry.job);
    queue.succeed(entry.id);
  }
  return seen;
}

test('s1 dequeue hands back the job that has been waiting longest', () => {
  const q = new JobQueue();
  const a = q.enqueue({ to: 'a' });
  const b = q.enqueue({ to: 'b' });
  const c = q.enqueue({ to: 'c' });
  assert.ok(typeof a === 'string' && a.length > 0, 'enqueue hands back an id');
  assert.strictEqual(new Set([a, b, c]).size, 3, 'every job gets its own id');
  assert.strictEqual(q.size(), 3);

  const first = q.dequeue(0);
  assert.deepStrictEqual(first.job, { to: 'a' }, 'the oldest job goes out first');
  assert.strictEqual(first.id, a);
  assert.strictEqual(q.size(), 2, 'a job that has gone out is not still waiting');

  assert.deepStrictEqual(q.dequeue(0).job, { to: 'b' });
  assert.deepStrictEqual(q.dequeue(0).job, { to: 'c' });
  assert.strictEqual(q.size(), 0);
  assert.strictEqual(q.dequeue(0), null, 'an empty queue hands back nothing');

  const later = new JobQueue();
  later.enqueue('x');
  later.dequeue(0);
  later.enqueue('y');
  later.enqueue('z');
  assert.strictEqual(later.dequeue(0).job, 'y', 'a job added later still queues behind the ones before it');
  assert.strictEqual(later.dequeue(0).job, 'z');
});

test('s2 a job stops going out once it has used its attempts', () => {
  const q = new JobQueue();
  const id = q.enqueue('payout-1');
  for (let i = 1; i <= 3; i += 1) {
    const entry = q.dequeue(0);
    assert.ok(entry, 'the job should still go out on attempt ' + i);
    assert.strictEqual(entry.id, id);
    assert.strictEqual(entry.attempts, i, 'attempts counts how many times it has gone out');
    q.fail(entry.id);
  }
  assert.strictEqual(q.dequeue(0), null, 'three attempts is the whole allowance');
  assert.strictEqual(q.size(), 0, 'a job that has used them all is not still waiting');

  const handOuts = (queue) => {
    let count = 0;
    for (let guard = 0; guard < 40; guard += 1) {
      const entry = queue.dequeue(0);
      if (!entry) return count;
      count += 1;
      queue.fail(entry.id);
    }
    return count;
  };

  const five = new JobQueue({ maxAttempts: 5 });
  five.enqueue('payout-2');
  assert.strictEqual(handOuts(five), 5, 'the configured cap is the number of hand-outs');

  const one = new JobQueue({ maxAttempts: 1 });
  one.enqueue('payout-3');
  assert.strictEqual(handOuts(one), 1, 'a cap of one means one go');

  for (const junk of [0, -2, 2.5, '4', null, NaN, Infinity, true]) {
    const odd = new JobQueue({ maxAttempts: junk });
    odd.enqueue('payout-4');
    assert.strictEqual(handOuts(odd), 3, 'an unusable maxAttempts falls back to 3');
  }

  const good = new JobQueue();
  const okId = good.enqueue('payout-5');
  const entry = good.dequeue(0);
  assert.strictEqual(entry.id, okId);
  good.succeed(entry.id);
  assert.strictEqual(good.size(), 0);
  assert.strictEqual(good.dequeue(0), null, 'a job that went through does not come back');
});

test('s3 a job that runs out of attempts lands on the dead-letter list', () => {
  const q = new JobQueue();
  const id = q.enqueue({ payout: 12 });
  for (let i = 0; i < 2; i += 1) {
    const entry = q.dequeue(0);
    assert.strictEqual(q.fail(entry.id, { reason: 'connection refused' }), 'requeued');
  }
  const last = q.dequeue(0);
  assert.strictEqual(q.fail(last.id, { reason: 'connection refused' }), 'dead');

  const dead = q.deadLetters();
  assert.strictEqual(dead.length, 1);
  assert.strictEqual(dead[0].id, id);
  assert.deepStrictEqual(dead[0].job, { payout: 12 });
  assert.strictEqual(dead[0].attempts, 3);
  assert.strictEqual(dead[0].reason, 'connection refused');
  assert.strictEqual(q.size(), 0, 'a dead letter is not waiting');
  assert.strictEqual(q.dequeue(0), null, 'and it never goes out again');

  assert.strictEqual(q.fail('j999'), null, 'no job went out under that id');
  assert.strictEqual(q.fail(id), null, 'that one is dead, not out with a worker');

  const nameless = new JobQueue({ maxAttempts: 1 });
  nameless.enqueue('a');
  const only = nameless.dequeue(0);
  assert.strictEqual(nameless.fail(only.id), 'dead');
  const recorded = nameless.deadLetters()[0];
  assert.ok(
    typeof recorded.reason === 'string' && recorded.reason.length > 0,
    'a dead letter always carries some reason'
  );

  const ordered = new JobQueue({ maxAttempts: 1 });
  ordered.enqueue('first');
  ordered.enqueue('second');
  const one = ordered.dequeue(0);
  ordered.fail(one.id, { reason: 'one' });
  const two = ordered.dequeue(0);
  ordered.fail(two.id, { reason: 'two' });
  assert.deepStrictEqual(ordered.deadLetters().map((d) => d.job), ['first', 'second'], 'oldest first');
  assert.deepStrictEqual(ordered.deadLetters().map((d) => d.reason), ['one', 'two']);
});

test('s4 a lease that runs out puts the job back, and an ack ends it', () => {
  const q = new JobQueue({ visibilityMs: 1000 });
  const id = q.enqueue('report');
  const entry = q.dequeue(5000);
  assert.strictEqual(entry.id, id);
  assert.strictEqual(q.size(), 0, 'a job out on a lease is not waiting');
  assert.strictEqual(q.sweep(5999), 0, 'the lease has not run out yet');
  assert.strictEqual(q.sweep(6000), 1, 'a deadline exactly equal to now has been reached');
  assert.strictEqual(q.size(), 1);

  const again = q.dequeue(6000);
  assert.strictEqual(again.id, id);
  assert.strictEqual(again.attempts, 2, 'a reclaimed job has still used an attempt');
  assert.strictEqual(q.succeed(again.id), true);
  assert.strictEqual(q.succeed(again.id), false, 'nothing is out under that id any more');
  assert.strictEqual(q.sweep(999999), 0);
  assert.strictEqual(q.size(), 0);

  const short = new JobQueue({ visibilityMs: 10, maxAttempts: 2 });
  short.enqueue('stuck');
  short.dequeue(0);
  assert.strictEqual(short.sweep(10), 1);
  short.dequeue(20);
  assert.strictEqual(short.sweep(30), 1, 'the last reclaim still counts as one moved');
  assert.strictEqual(short.size(), 0, 'out of attempts, so it is not waiting');
  const buried = short.deadLetters();
  assert.strictEqual(buried.length, 1, 'a lease that runs out on the last attempt is a dead letter');
  assert.strictEqual(buried[0].job, 'stuck');
  assert.ok(typeof buried[0].reason === 'string' && buried[0].reason.length > 0);

  for (const junk of [0, -1, 1.5, '1000', null]) {
    const odd = new JobQueue({ visibilityMs: junk });
    odd.enqueue('x');
    odd.dequeue(0);
    assert.strictEqual(odd.sweep(29999), 0, 'an unusable visibilityMs falls back to 30000');
    assert.strictEqual(odd.sweep(30000), 1);
  }
});

test('s5 lanes are served in order and a job keeps its place in its own lane', () => {
  const q = new JobQueue();
  q.enqueue('n1', { priority: 'normal' });
  q.enqueue('l1', { priority: 'low' });
  q.enqueue('h1', { priority: 'high' });
  q.enqueue('n2');
  q.enqueue('h2', { priority: 'high' });
  q.enqueue('x1', { priority: 'urgent' });
  assert.deepStrictEqual(orderOut(q, 0), ['h1', 'h2', 'n1', 'n2', 'x1', 'l1']);

  const plain = new JobQueue();
  plain.enqueue('only');
  assert.strictEqual(plain.dequeue(0).priority, 'normal', 'no priority at all is the normal lane');
  const deep = new JobQueue();
  deep.enqueue('slow', { priority: 'low' });
  assert.strictEqual(deep.dequeue(0).priority, 'low', 'the entry says which lane it came from');

  const back = new JobQueue();
  back.enqueue('a');
  back.enqueue('b');
  back.enqueue('c');
  const first = back.dequeue(0);
  assert.strictEqual(first.job, 'a');
  back.fail(first.id, { reason: 'flaky' });
  assert.strictEqual(back.dequeue(0).job, 'a', 'a requeued job returns to its own place in its lane');

  const swept = new JobQueue({ visibilityMs: 5 });
  swept.enqueue('p', { priority: 'high' });
  swept.enqueue('q', { priority: 'high' });
  assert.strictEqual(swept.dequeue(0).job, 'p');
  assert.strictEqual(swept.sweep(100), 1);
  assert.strictEqual(swept.dequeue(100).job, 'p', 'a reclaimed job keeps its place too');
  assert.strictEqual(swept.dequeue(100).job, 'q');

  const lanes = new JobQueue();
  lanes.enqueue('low-first', { priority: 'low' });
  lanes.enqueue('high-later', { priority: 'high' });
  assert.deepStrictEqual(orderOut(lanes, 0), ['high-later', 'low-first']);
});

test('s6 an idempotency key keeps a second copy of the same job out of the queue', () => {
  const q = new JobQueue();
  const first = q.enqueue({ n: 1 }, { key: 'invoice-9' });
  const second = q.enqueue({ n: 2 }, { key: 'invoice-9' });
  assert.strictEqual(second, first, 'the duplicate hands back the id already on the queue');
  assert.strictEqual(q.size(), 1, 'and adds nothing');

  const entry = q.dequeue(0);
  assert.deepStrictEqual(entry.job, { n: 1 }, 'the payload already queued is the one that stays');
  assert.strictEqual(q.enqueue({ n: 3 }, { key: 'invoice-9' }), first, 'the key is held while it is out');
  assert.strictEqual(q.size(), 0);

  assert.strictEqual(q.fail(entry.id, { reason: 'gateway said no' }), 'requeued');
  assert.strictEqual(q.enqueue({ n: 4 }, { key: 'invoice-9' }), first, 'and while it waits to go again');
  assert.strictEqual(q.size(), 1);

  const retried = q.dequeue(0);
  assert.strictEqual(q.succeed(retried.id), true);
  const fresh = q.enqueue({ n: 5 }, { key: 'invoice-9' });
  assert.notStrictEqual(fresh, first, 'the key is free once the job has gone through');
  assert.strictEqual(q.size(), 1);
  assert.deepStrictEqual(q.dequeue(0).job, { n: 5 });

  const doomedQueue = new JobQueue({ maxAttempts: 1 });
  const doomed = doomedQueue.enqueue('a', { key: 'k' });
  const going = doomedQueue.dequeue(0);
  assert.strictEqual(doomedQueue.fail(going.id, { reason: 'no' }), 'dead');
  const after = doomedQueue.enqueue('b', { key: 'k' });
  assert.notStrictEqual(after, doomed, 'the key is free once the job is a dead letter');
  assert.strictEqual(doomedQueue.size(), 1);

  const unkeyed = new JobQueue();
  unkeyed.enqueue('same');
  unkeyed.enqueue('same');
  assert.strictEqual(unkeyed.size(), 2, 'a job with no key is never deduplicated');

  const odd = new JobQueue();
  odd.enqueue('a', { key: '' });
  odd.enqueue('b', { key: '' });
  odd.enqueue('c', { key: 7 });
  odd.enqueue('d', { key: 7 });
  assert.strictEqual(odd.size(), 4, 'only a non-empty string is a key');

  const two = new JobQueue();
  const k1 = two.enqueue('x', { key: 'a' });
  const k2 = two.enqueue('y', { key: 'b' });
  assert.notStrictEqual(k1, k2);
  assert.strictEqual(two.size(), 2, 'different keys are different jobs');
});

test('s7 runOne acks what went through and hands back what did not', async () => {
  const q = new JobQueue();
  q.enqueue('ok-job');
  const seen = [];
  const good = await runOne(q, async (job, entry) => {
    seen.push([job, entry.attempts]);
    return 'delivered';
  }, 0);
  assert.strictEqual(good.ran, true);
  assert.strictEqual(good.outcome, 'succeeded');
  assert.strictEqual(good.value, 'delivered');
  assert.ok(typeof good.id === 'string' && good.id.length > 0);
  assert.deepStrictEqual(seen, [['ok-job', 1]], 'the handler is called with the payload and the entry');
  assert.strictEqual(q.size(), 0);
  assert.strictEqual(q.sweep(999999), 0, 'a job that went through is not still out on a lease');

  assert.deepStrictEqual(await runOne(q, async () => 'x', 0), { ran: false }, 'nothing to run');

  const flaky = new JobQueue();
  flaky.enqueue('flaky');
  const rejected = await runOne(flaky, async () => {
    throw new Error('socket hang up');
  }, 0);
  assert.strictEqual(rejected.ran, true);
  assert.strictEqual(rejected.outcome, 'requeued', 'nothing escapes runOne');
  assert.strictEqual(flaky.size(), 1, 'the job went back on the queue');
  assert.strictEqual(flaky.sweep(999999), 0, 'and it is not still out on a lease as well');

  const sync = new JobQueue();
  sync.enqueue('sync-boom');
  const threw = await runOne(sync, () => {
    throw new Error('bad payload');
  }, 0);
  assert.strictEqual(threw.ran, true);
  assert.strictEqual(threw.outcome, 'requeued', 'a synchronous throw is the same thing');
  assert.strictEqual(sync.size(), 1);

  const doomed = new JobQueue({ maxAttempts: 1 });
  doomed.enqueue('doomed');
  const dead = await runOne(doomed, async () => {
    throw new Error('rejected by the gateway');
  }, 0);
  assert.strictEqual(dead.outcome, 'dead');
  assert.strictEqual(doomed.deadLetters().length, 1);
  assert.strictEqual(doomed.deadLetters()[0].reason, 'rejected by the gateway', 'the message is the reason');

  const lanes = new JobQueue();
  lanes.enqueue('normal-one');
  lanes.enqueue('high-one', { priority: 'high' });
  const picked = await runOne(lanes, async (job) => job, 0);
  assert.strictEqual(picked.value, 'high-one', 'runOne takes whatever the queue would hand out');
});

test('s8 a drain works the queue down and can be capped', async () => {
  const q = new JobQueue();
  q.enqueue('a');
  q.enqueue('b');
  q.enqueue('c');
  let tick = 0;
  const done = [];
  const run = await drain(q, async (job) => {
    done.push(job);
    return job;
  }, { now: () => { tick += 1; return tick; } });
  assert.deepStrictEqual(done, ['a', 'b', 'c']);
  assert.deepStrictEqual(run, { runs: 3, succeeded: 3, requeued: 0, dead: 0, stopped: false });
  assert.strictEqual(q.size(), 0);

  const empty = await drain(new JobQueue(), async () => 'x', { now: () => 0 });
  assert.deepStrictEqual(empty, { runs: 0, succeeded: 0, requeued: 0, dead: 0, stopped: false });

  const failing = new JobQueue();
  failing.enqueue('bad');
  const worked = await drain(failing, async () => {
    throw new Error('nope');
  }, { now: () => 0 });
  assert.strictEqual(worked.runs, 3, 'a failing job is retried inside the same drain');
  assert.strictEqual(worked.requeued, 2);
  assert.strictEqual(worked.dead, 1);
  assert.strictEqual(worked.succeeded, 0);
  assert.strictEqual(worked.stopped, false);
  assert.strictEqual(failing.deadLetters().length, 1);

  const growing = new JobQueue();
  growing.enqueue('n1');
  growing.enqueue('n2');
  const seen = [];
  await drain(growing, async (job) => {
    seen.push(job);
    if (job === 'n1') growing.enqueue('h1', { priority: 'high' });
  }, { now: () => 0 });
  assert.deepStrictEqual(seen, ['n1', 'h1', 'n2'], 'work queued mid-drain is picked up in lane order');

  const capped = new JobQueue();
  for (const job of ['a', 'b', 'c', 'd', 'e']) capped.enqueue(job);
  const stopped = await drain(capped, async () => 'ok', { now: () => 0, maxRuns: 2 });
  assert.strictEqual(stopped.runs, 2);
  assert.strictEqual(stopped.stopped, true);
  assert.strictEqual(capped.size(), 3, 'what it did not get to is still waiting');

  const exact = new JobQueue();
  exact.enqueue('only');
  const onTheNose = await drain(exact, async () => 'ok', { now: () => 0, maxRuns: 1 });
  assert.strictEqual(onTheNose.runs, 1);
  assert.strictEqual(onTheNose.stopped, true, 'coming out on the ceiling is coming out on the ceiling');

  for (const junk of [0, -1, 1.5, '2', null]) {
    const loose = new JobQueue();
    for (const job of ['a', 'b', 'c']) loose.enqueue(job);
    const all = await drain(loose, async () => 'ok', { now: () => 0, maxRuns: junk });
    assert.strictEqual(all.runs, 3, 'an unusable maxRuns is no ceiling at all');
    assert.strictEqual(all.stopped, false);
  }

  const bare = new JobQueue();
  bare.enqueue('x');
  const bareRun = await drain(bare, async () => 'ok');
  assert.strictEqual(bareRun.runs, 1, 'no options at all still works');
  assert.strictEqual(bareRun.succeeded, 1);
});

test('s9 a failure can hold a job back and only a ready job goes out', async () => {
  const q = new JobQueue();
  q.enqueue('n', { priority: 'normal' });
  q.enqueue('h', { priority: 'high' });
  const high = q.dequeue(1000);
  assert.strictEqual(high.job, 'h');
  assert.strictEqual(q.fail(high.id, { reason: 'rate limited', retryAfterMs: 500, now: 1000 }), 'requeued');
  assert.strictEqual(q.size(), 2, 'a job being held back is still on the queue');
  assert.strictEqual(q.ready(1000), 1, 'but only one of them can go out now');
  assert.strictEqual(q.dequeue(1000).job, 'n', 'a held high job does not block a ready normal one');
  assert.strictEqual(q.dequeue(1400), null, 'nothing else is ready yet');
  assert.strictEqual(q.ready(1499), 0);
  assert.strictEqual(q.ready(1500), 1, 'the hold is over once now has reached it');
  const released = q.dequeue(1500);
  assert.strictEqual(released.job, 'h');
  assert.strictEqual(released.attempts, 2);

  const measured = new JobQueue();
  measured.enqueue('x');
  const one = measured.dequeue(0);
  measured.fail(one.id, { reason: 'busy', retryAfterMs: 100, now: 9000 });
  assert.strictEqual(measured.dequeue(9099), null, 'the hold runs from the reading it was given');
  assert.strictEqual(measured.dequeue(9100).job, 'x');

  for (const junk of ['100', null, NaN, Infinity, -50, undefined, true]) {
    const odd = new JobQueue();
    odd.enqueue('y');
    const entry = odd.dequeue(0);
    odd.fail(entry.id, { reason: 'busy', retryAfterMs: junk, now: 0 });
    assert.ok(odd.dequeue(0), 'an unusable retryAfterMs is no hold at all');
  }

  const cleared = new JobQueue();
  cleared.enqueue('z');
  const held = cleared.dequeue(0);
  cleared.fail(held.id, { reason: 'busy', retryAfterMs: 50, now: 0 });
  const back = cleared.dequeue(50);
  assert.strictEqual(back.job, 'z');
  cleared.fail(back.id, { reason: 'busy again' });
  assert.ok(cleared.dequeue(50), 'a failure with no hold on it is ready straight away');

  const reclaimed = new JobQueue({ visibilityMs: 10 });
  reclaimed.enqueue('w');
  reclaimed.dequeue(0);
  assert.strictEqual(reclaimed.sweep(10), 1);
  assert.strictEqual(reclaimed.ready(10), 1, 'a sweep does not put a hold on what it reclaims');

  const gated = new JobQueue();
  gated.enqueue('gated');
  const gate = gated.dequeue(0);
  gated.fail(gate.id, { reason: 'wait your turn', retryAfterMs: 200, now: 0 });
  assert.deepStrictEqual(await runOne(gated, async () => 'ok', 199), { ran: false }, 'the runner passes its reading down');
  const went = await runOne(gated, async () => 'ok', 200);
  assert.strictEqual(went.ran, true);
  assert.strictEqual(went.outcome, 'succeeded');

  const waiting = new JobQueue();
  waiting.enqueue('later');
  const parked = waiting.dequeue(0);
  waiting.fail(parked.id, { reason: 'rate limited', retryAfterMs: 1000, now: 0 });
  const idle = await drain(waiting, async () => 'ok', { now: () => 500 });
  assert.strictEqual(idle.runs, 0, 'a drain comes out cleanly when everything left is held');
  assert.strictEqual(idle.stopped, false);
  assert.strictEqual(waiting.size(), 1, 'and the job is still there');
  const later = await drain(waiting, async () => 'ok', { now: () => 1000 });
  assert.strictEqual(later.runs, 1);

  const stepping = new JobQueue();
  stepping.enqueue('held-briefly');
  const briefly = stepping.dequeue(0);
  stepping.fail(briefly.id, { reason: 'rate limited', retryAfterMs: 150, now: 0 });
  stepping.enqueue('ready-now');
  let readings = 0;
  const stepped = await drain(stepping, async () => 'ok', {
    now: () => {
      readings += 1;
      return readings * 100;
    },
  });
  assert.strictEqual(stepped.runs, 2, 'the clock is read once per run, so a hold that runs out mid-drain is picked up');
  assert.strictEqual(stepped.succeeded, 2);

  const clockless = new JobQueue();
  clockless.enqueue('long-parked');
  const parkedLong = clockless.dequeue(0);
  clockless.fail(parkedLong.id, { reason: 'rate limited', retryAfterMs: 1000, now: 0 });
  const defaulted = await drain(clockless, async () => 'ok', {});
  assert.strictEqual(defaulted.runs, 1, 'with no clock of its own the drain reads the current time');

  const unstamped = new JobQueue();
  unstamped.enqueue('no-reading');
  const noReading = unstamped.dequeue(0);
  unstamped.fail(noReading.id, { reason: 'rate limited', retryAfterMs: 60000 });
  assert.strictEqual(unstamped.size(), 1);
  assert.strictEqual(unstamped.ready(Date.now()), 0, 'with no reading in the details the hold runs from the current time');
  assert.strictEqual(unstamped.ready(Date.now() + 60000), 1, 'and it is over a minute from now');
});

test('s10 a queue survives a snapshot and comes back the same', () => {
  const q = new JobQueue({ maxAttempts: 2, visibilityMs: 250 });
  const a = q.enqueue('a', { priority: 'high', key: 'ka' });
  const b = q.enqueue('b');
  const c = q.enqueue('c', { priority: 'low' });
  const d = q.enqueue('d', { key: 'kd' });

  const onLoan = q.dequeue(0);
  assert.strictEqual(onLoan.job, 'a');
  const held = q.dequeue(0);
  assert.strictEqual(held.job, 'b');
  q.fail(held.id, { reason: 'flaky', retryAfterMs: 100, now: 0 });
  const doomed = q.dequeue(0);
  assert.strictEqual(doomed.job, 'd');
  q.fail(doomed.id, { reason: 'gateway' });
  q.fail(q.dequeue(0).id, { reason: 'gateway said no' });
  assert.strictEqual(q.deadLetters().length, 1);

  const snap = JSON.parse(JSON.stringify(q.snapshot()));
  const back = fromSnapshot(snap);
  assert.ok(back && typeof back.dequeue === 'function', 'a snapshot comes back as a queue');
  assert.strictEqual(back.size(), 3, 'the two waiting jobs and the one that was out on a lease');
  assert.strictEqual(back.ready(0), 2, 'the job that was being held back still is');
  assert.strictEqual(back.deadLetters().length, 1);
  assert.strictEqual(back.deadLetters()[0].job, 'd');
  assert.strictEqual(back.deadLetters()[0].reason, 'gateway said no');
  assert.strictEqual(back.deadLetters()[0].attempts, 2);

  const revived = back.dequeue(0);
  assert.strictEqual(revived.job, 'a', 'the leased job is waiting again and the high lane goes first');
  assert.strictEqual(revived.id, a);
  assert.strictEqual(revived.attempts, 2, 'it had already been handed out once');
  assert.strictEqual(revived.priority, 'high');
  assert.strictEqual(back.enqueue('a-again', { key: 'ka' }), a, 'and it still holds its key');

  assert.strictEqual(back.dequeue(0).job, 'c', 'the low lane goes before a job that is not ready');
  assert.strictEqual(back.dequeue(99), null);
  const late = back.dequeue(100);
  assert.strictEqual(late.job, 'b');
  assert.strictEqual(late.attempts, 2);
  assert.strictEqual(back.fail(late.id, { reason: 'still flaky' }), 'dead', 'the settings came back too');
  assert.strictEqual(back.deadLetters().length, 2);
  assert.strictEqual(back.sweep(249), 0, 'the visibility window came back with the settings');
  assert.strictEqual(back.sweep(250), 2, 'both leases ran out at the same moment');

  const second = fromSnapshot(snap);
  const added = second.enqueue('e');
  assert.ok(![a, b, c, d].includes(added), 'a new job does not reuse an id that came back');
  assert.deepStrictEqual(
    orderOut(second, 1000),
    ['a', 'b', 'e', 'c'],
    'the new job queues behind the restored ones in its lane'
  );

  assert.strictEqual(fromSnapshot(null), null);
  assert.strictEqual(fromSnapshot('a queue'), null);
  assert.strictEqual(fromSnapshot(42), null);
  assert.strictEqual(fromSnapshot({ dead: [] }), null, 'no jobs list is not a snapshot');
});

test('s11 a permanent failure dies at once, the dead list is bounded, and a dead letter can be replayed', () => {
  const q = new JobQueue({ maxAttempts: 5 });
  const id = q.enqueue('card-declined', { priority: 'high', key: 'pay-1' });
  const entry = q.dequeue(0);
  assert.strictEqual(q.fail(entry.id, { reason: 'card declined', permanent: true }), 'dead');
  assert.strictEqual(q.size(), 0);
  const dead = q.deadLetters();
  assert.strictEqual(dead.length, 1);
  assert.strictEqual(dead[0].reason, 'card declined');
  assert.strictEqual(dead[0].attempts, 1, 'it died on its first attempt with four left');

  const other = q.enqueue('a different payment', { key: 'pay-1' });
  assert.notStrictEqual(other, id, 'the key went with it');
  assert.strictEqual(q.requeueDead(id), false, 'its key belongs to a live job now');
  assert.strictEqual(q.deadLetters().length, 1, 'and the dead letter stays where it is');

  const live = q.dequeue(0);
  assert.strictEqual(q.succeed(live.id), true);
  assert.strictEqual(q.requeueDead(id), true);
  assert.strictEqual(q.deadLetters().length, 0);
  assert.strictEqual(q.size(), 1);
  const replayed = q.dequeue(0);
  assert.strictEqual(replayed.id, id, 'same id');
  assert.strictEqual(replayed.job, 'card-declined');
  assert.strictEqual(replayed.priority, 'high');
  assert.strictEqual(replayed.attempts, 1, 'a replayed job starts its attempts over');
  assert.strictEqual(q.enqueue('dup', { key: 'pay-1' }), id, 'the replay took its key back');
  assert.strictEqual(q.requeueDead('j999'), false, 'nothing under that id is dead');

  const lane = new JobQueue({ maxAttempts: 1 });
  const older = lane.enqueue('older');
  lane.enqueue('newer');
  lane.fail(lane.dequeue(0).id, { reason: 'boom' });
  assert.strictEqual(lane.requeueDead(older), true);
  assert.strictEqual(lane.dequeue(0).job, 'older', 'a replayed job goes back to its own place in its lane');

  const bounded = new JobQueue({ maxAttempts: 1, maxDead: 3 });
  for (const job of ['a', 'b', 'c', 'd', 'e']) {
    bounded.enqueue(job);
    bounded.fail(bounded.dequeue(0).id, { reason: 'no ' + job });
  }
  assert.deepStrictEqual(bounded.deadLetters().map((x) => x.job), ['c', 'd', 'e'], 'the oldest go first');
  assert.deepStrictEqual(bounded.deadLetters().map((x) => x.reason), ['no c', 'no d', 'no e']);

  for (const junk of [0, -1, 2.5, '3', null]) {
    const loose = new JobQueue({ maxAttempts: 1, maxDead: junk });
    for (const job of ['a', 'b', 'c', 'd']) {
      loose.enqueue(job);
      loose.fail(loose.dequeue(0).id, { reason: 'no' });
    }
    assert.strictEqual(loose.deadLetters().length, 4, 'an unusable maxDead is no bound at all');
  }

  const survivors = new JobQueue();
  survivors.enqueue('x');
  survivors.enqueue('y');
  survivors.fail(survivors.dequeue(0).id, { reason: 'bad address', permanent: true });
  assert.strictEqual(survivors.size(), 1, 'one job died, not the queue');
  assert.strictEqual(survivors.dequeue(0).job, 'y');

  const ordinary = new JobQueue();
  ordinary.enqueue('z');
  assert.strictEqual(
    ordinary.fail(ordinary.dequeue(0).id, { reason: 'transient', permanent: false }),
    'requeued',
    'only a true kills the job outright'
  );
  const bare = new JobQueue();
  bare.enqueue('w');
  assert.strictEqual(bare.fail(bare.dequeue(0).id, { reason: 'transient' }), 'requeued');
});

test('s12 a lane streak cap lets a lower lane through without disturbing the default order', () => {
  const q = new JobQueue({ maxStreak: 2 });
  for (const job of ['h1', 'h2', 'h3', 'h4', 'h5']) q.enqueue(job, { priority: 'high' });
  q.enqueue('n1');
  q.enqueue('n2');
  assert.deepStrictEqual(orderOut(q, 0), ['h1', 'h2', 'n1', 'h3', 'h4', 'n2', 'h5']);

  const solo = new JobQueue({ maxStreak: 2 });
  for (const job of ['a', 'b', 'c', 'd']) solo.enqueue(job, { priority: 'high' });
  const seen = [];
  for (let i = 0; i < 4; i += 1) {
    const entry = solo.dequeue(0);
    seen.push(entry.job);
    solo.succeed(entry.id);
  }
  assert.deepStrictEqual(seen, ['a', 'b', 'c', 'd'], 'with no other lane ready the lane keeps its turn');
  solo.enqueue('low-one', { priority: 'low' });
  solo.enqueue('e', { priority: 'high' });
  assert.strictEqual(solo.dequeue(0).job, 'low-one', 'four in a row is already past the cap');

  const held = new JobQueue({ maxStreak: 1 });
  held.enqueue('n1');
  const parked = held.dequeue(0);
  assert.strictEqual(parked.job, 'n1');
  held.fail(parked.id, { reason: 'rate limited', retryAfterMs: 1000, now: 0 });
  held.enqueue('h1', { priority: 'high' });
  held.enqueue('h2', { priority: 'high' });
  assert.strictEqual(held.dequeue(0).job, 'h1');
  assert.strictEqual(held.dequeue(0).job, 'h2', 'a job that is not ready is not a lane waiting its turn');
  assert.strictEqual(held.dequeue(1000).job, 'n1', 'once it is ready the cap sends it out');

  const quiet = new JobQueue({ maxStreak: 2 });
  quiet.enqueue('h1', { priority: 'high' });
  quiet.enqueue('h2', { priority: 'high' });
  quiet.enqueue('n1');
  const one = quiet.dequeue(0);
  assert.strictEqual(one.job, 'h1');
  quiet.fail(one.id, { reason: 'flaky' });
  const two = quiet.dequeue(0);
  assert.strictEqual(two.job, 'h1', 'it kept its place in the lane');
  quiet.succeed(two.id);
  assert.strictEqual(quiet.dequeue(0).job, 'n1', 'two hand-outs from a lane is two, however they went');

  const reclaimedStreak = new JobQueue({ maxStreak: 2, visibilityMs: 5 });
  reclaimedStreak.enqueue('h1', { priority: 'high' });
  reclaimedStreak.enqueue('h2', { priority: 'high' });
  reclaimedStreak.enqueue('n1');
  assert.strictEqual(reclaimedStreak.dequeue(0).job, 'h1');
  assert.strictEqual(reclaimedStreak.sweep(100), 1, 'the lease ran out');
  assert.strictEqual(reclaimedStreak.dequeue(100).job, 'h1', 'a sweep is not a hand-out, so the count did not move');
  assert.strictEqual(reclaimedStreak.dequeue(100).job, 'n1', 'and two hand-outs from that lane is still two');

  const choice = new JobQueue({ maxStreak: 1 });
  choice.enqueue('h1', { priority: 'high' });
  choice.enqueue('l1', { priority: 'low' });
  choice.enqueue('n1');
  choice.enqueue('h2', { priority: 'high' });
  assert.deepStrictEqual(
    orderOut(choice, 0),
    ['h1', 'n1', 'h2', 'l1'],
    'the turn goes to the highest-priority lane that is not the one that just went'
  );

  for (const junk of [undefined, 0, -1, 1.5, '2', null]) {
    const off = new JobQueue(junk === undefined ? {} : { maxStreak: junk });
    for (const job of ['h1', 'h2', 'h3']) off.enqueue(job, { priority: 'high' });
    off.enqueue('n1');
    assert.deepStrictEqual(
      orderOut(off, 0),
      ['h1', 'h2', 'h3', 'n1'],
      'without a usable maxStreak the lanes stay strict'
    );
  }
});

