'use strict';

// In-memory job queue behind the delivery worker. A job is any plain value.
// The queue hands one job out at a time and the worker reports back whether it
// went through; nothing here talks to the network.

const DEFAULT_MAX_ATTEMPTS = 3;
const DEFAULT_VISIBILITY_MS = 30000;

// Highest priority first; the index doubles as the lane's rank.
const LANES = ['high', 'normal', 'low'];

function laneOf(value) {
  return LANES.indexOf(value) === -1 ? 'normal' : value;
}

function rankOf(priority) {
  const index = LANES.indexOf(priority);
  return index === -1 ? 1 : index;
}

function positiveWhole(value, fallback) {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) return value;
  return fallback;
}

function millis(value) {
  return typeof value === 'number' && Number.isFinite(value) ? value : Date.now();
}

function usableHold(value) {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0;
}

function keyOf(value) {
  return typeof value === 'string' && value.length > 0 ? value : null;
}

class JobQueue {
  constructor(options) {
    const opts = options && typeof options === 'object' ? options : {};
    this.maxAttempts = positiveWhole(opts.maxAttempts, DEFAULT_MAX_ATTEMPTS);
    this.visibilityMs = positiveWhole(opts.visibilityMs, DEFAULT_VISIBILITY_MS);
    this.maxDead = positiveWhole(opts.maxDead, null);
    this.maxStreak = positiveWhole(opts.maxStreak, null);
    this.waiting = [];
    this.leased = new Map();
    this.dead = [];
    this.reserved = new Map();
    this.seq = 0;
    this.lastLane = null;
    this.laneRun = 0;
  }

  // Adds a job and hands back the id the worker will report against. A job
  // carrying a key already held by a live job is not added at all.
  enqueue(job, options) {
    const opts = options && typeof options === 'object' ? options : {};
    const key = keyOf(opts.key);
    if (key !== null && this.reserved.has(key)) return this.reserved.get(key);
    this.seq += 1;
    const entry = {
      id: 'j' + this.seq,
      job: job,
      attempts: 0,
      priority: laneOf(opts.priority),
      seq: this.seq,
      key: key,
      notBefore: 0,
    };
    this.waiting.push(entry);
    if (key !== null) this.reserved.set(key, entry.id);
    return entry.id;
  }

  // How many jobs are on the queue, held back or not.
  size() {
    return this.waiting.length;
  }

  // How many of those could actually go out at that moment.
  ready(now) {
    const at = millis(now);
    return this.waiting.filter((entry) => entry.notBefore <= at).length;
  }

  // Lane order, then first-enqueued order inside the lane. The streak cap, when
  // one is configured, lets another lane in once one lane has had its run.
  pickAt(at) {
    const ready = this.waiting.filter((entry) => entry.notBefore <= at);
    if (ready.length === 0) return null;
    const best = (list) =>
      list.slice().sort((a, b) => rankOf(a.priority) - rankOf(b.priority) || a.seq - b.seq)[0];
    if (this.maxStreak !== null && this.lastLane !== null && this.laneRun >= this.maxStreak) {
      const others = ready.filter((entry) => entry.priority !== this.lastLane);
      if (others.length > 0) return best(others);
    }
    return best(ready);
  }

  // Takes one job off the queue and puts it on a lease.
  dequeue(now) {
    const at = millis(now);
    const entry = this.pickAt(at);
    if (!entry) return null;
    this.waiting.splice(this.waiting.indexOf(entry), 1);
    entry.attempts += 1;
    entry.notBefore = 0;
    entry.deadline = at + this.visibilityMs;
    this.leased.set(entry.id, entry);
    if (this.lastLane === entry.priority) {
      this.laneRun += 1;
    } else {
      this.lastLane = entry.priority;
      this.laneRun = 1;
    }
    return { id: entry.id, job: entry.job, attempts: entry.attempts, priority: entry.priority };
  }

  // The worker got it through: the lease ends and the key is let go.
  succeed(id) {
    const entry = this.leased.get(id);
    if (!entry) return false;
    this.leased.delete(id);
    this.release(entry);
    return true;
  }

  // The worker did not get it through. Back on the queue unless it has run out
  // of attempts or the caller says there is no point trying again.
  fail(id, details) {
    const entry = this.leased.get(id);
    if (!entry) return null;
    const info = details && typeof details === 'object' ? details : {};
    const reason =
      typeof info.reason === 'string' && info.reason.length > 0
        ? info.reason
        : 'the worker reported a failure';
    this.leased.delete(id);
    if (info.permanent === true || entry.attempts >= this.maxAttempts) {
      this.bury(entry, reason);
      return 'dead';
    }
    entry.notBefore = usableHold(info.retryAfterMs) ? millis(info.now) + info.retryAfterMs : 0;
    this.waiting.push(entry);
    return 'requeued';
  }

  // Puts every lease that has run out back on the queue.
  sweep(now) {
    const at = millis(now);
    let moved = 0;
    for (const entry of Array.from(this.leased.values())) {
      if (entry.deadline > at) continue;
      this.leased.delete(entry.id);
      moved += 1;
      if (entry.attempts >= this.maxAttempts) {
        this.bury(entry, 'the lease ran out on the last attempt');
      } else {
        entry.notBefore = 0;
        this.waiting.push(entry);
      }
    }
    return moved;
  }

  deadLetters() {
    return this.dead.map((entry) => ({
      id: entry.id,
      job: entry.job,
      attempts: entry.attempts,
      reason: entry.reason,
    }));
  }

  // Puts a dead letter back on the queue in the place it used to hold.
  requeueDead(id) {
    const index = this.dead.findIndex((entry) => entry.id === id);
    if (index === -1) return false;
    const entry = this.dead[index];
    if (entry.key !== null && this.reserved.has(entry.key)) return false;
    this.dead.splice(index, 1);
    const revived = {
      id: entry.id,
      job: entry.job,
      attempts: 0,
      priority: entry.priority,
      seq: entry.seq,
      key: entry.key,
      notBefore: 0,
    };
    this.waiting.push(revived);
    if (revived.key !== null) this.reserved.set(revived.key, revived.id);
    return true;
  }

  snapshot() {
    const pack = (entry) => ({
      id: entry.id,
      job: entry.job,
      attempts: entry.attempts,
      priority: entry.priority,
      seq: entry.seq,
      key: entry.key,
      notBefore: entry.notBefore,
    });
    return {
      jobs: this.waiting.concat(Array.from(this.leased.values())).map(pack),
      dead: this.dead.map((entry) => ({
        id: entry.id,
        job: entry.job,
        attempts: entry.attempts,
        priority: entry.priority,
        seq: entry.seq,
        key: entry.key,
        reason: entry.reason,
      })),
      seq: this.seq,
      settings: {
        maxAttempts: this.maxAttempts,
        visibilityMs: this.visibilityMs,
        maxDead: this.maxDead,
        maxStreak: this.maxStreak,
      },
    };
  }

  // --- internals ------------------------------------------------------------

  release(entry) {
    if (entry.key !== null && this.reserved.get(entry.key) === entry.id) {
      this.reserved.delete(entry.key);
    }
  }

  bury(entry, reason) {
    this.release(entry);
    this.dead.push({
      id: entry.id,
      job: entry.job,
      attempts: entry.attempts,
      priority: entry.priority,
      seq: entry.seq,
      key: entry.key,
      reason: reason,
    });
    if (this.maxDead !== null) {
      while (this.dead.length > this.maxDead) this.dead.shift();
    }
  }
}

// Rebuilds a queue from snapshot(). Anything that is not a snapshot comes back
// as null. Jobs that were out on a lease come back waiting, because whatever
// was running them is gone.
function fromSnapshot(snapshot) {
  if (!snapshot || typeof snapshot !== 'object' || !Array.isArray(snapshot.jobs)) return null;
  const settings = snapshot.settings && typeof snapshot.settings === 'object' ? snapshot.settings : {};
  const queue = new JobQueue(settings);
  let highest = typeof snapshot.seq === 'number' ? snapshot.seq : 0;
  const seqOf = (raw) => (typeof raw.seq === 'number' ? raw.seq : 0);

  for (const raw of snapshot.jobs) {
    const entry = {
      id: raw.id,
      job: raw.job,
      attempts: typeof raw.attempts === 'number' ? raw.attempts : 0,
      priority: laneOf(raw.priority),
      seq: seqOf(raw),
      key: keyOf(raw.key),
      notBefore: typeof raw.notBefore === 'number' ? raw.notBefore : 0,
    };
    queue.waiting.push(entry);
    if (entry.key !== null) queue.reserved.set(entry.key, entry.id);
    if (entry.seq > highest) highest = entry.seq;
  }

  const buried = Array.isArray(snapshot.dead) ? snapshot.dead : [];
  for (const raw of buried) {
    queue.dead.push({
      id: raw.id,
      job: raw.job,
      attempts: typeof raw.attempts === 'number' ? raw.attempts : 0,
      priority: laneOf(raw.priority),
      seq: seqOf(raw),
      key: keyOf(raw.key),
      reason: raw.reason,
    });
    if (seqOf(raw) > highest) highest = seqOf(raw);
  }

  queue.seq = highest;
  return queue;
}

module.exports = { JobQueue, fromSnapshot };

