'use strict';

// The worker loop's only door into the queue. Nothing else in the service
// calls the queue directly, so whatever policy we want lives in here.
async function runOne(queue, handler, now) {
  const entry = queue.dequeue(now);
  if (!entry) return { ran: false };
  let value;
  try {
    value = await handler(entry.job, entry);
  } catch (err) {
    const reason =
      err && typeof err.message === 'string' && err.message.length > 0
        ? err.message
        : 'the handler threw';
    return { ran: true, id: entry.id, outcome: queue.fail(entry.id, { reason: reason }) };
  }
  queue.succeed(entry.id);
  return { ran: true, id: entry.id, outcome: 'succeeded', value: value };
}

function ceilingOf(value) {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) return value;
  return null;
}

// Works the queue down until there is nothing left that can go out.
async function drain(queue, handler, options) {
  const opts = options && typeof options === 'object' ? options : {};
  const reading = typeof opts.now === 'function' ? opts.now : Date.now;
  const ceiling = ceilingOf(opts.maxRuns);
  const tally = { runs: 0, succeeded: 0, requeued: 0, dead: 0, stopped: false };

  for (;;) {
    const result = await runOne(queue, handler, reading());
    if (!result.ran) return tally;
    tally.runs += 1;
    if (result.outcome === 'succeeded') tally.succeeded += 1;
    else if (result.outcome === 'requeued') tally.requeued += 1;
    else if (result.outcome === 'dead') tally.dead += 1;
    if (ceiling !== null && tally.runs >= ceiling) {
      tally.stopped = true;
      return tally;
    }
  }
}

module.exports = { runOne, drain };
